#include "airside/autonomy/experiment.hpp"
#include "airside/autonomy/scenario_loader.hpp"
#include <yaml-cpp/yaml.h>
#include <algorithm>
#include <cmath>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <limits>
#include <map>
#include <sstream>
#include <string_view>

namespace {
using namespace airside::autonomy;
struct Options { std::filesystem::path file="experiments/autonomy_robustness.yaml"; std::filesystem::path output; std::size_t workers{}; std::string selected_case; };
Options parse(int argc,char**argv){Options o;for(int i=1;i<argc;++i){std::string_view a=argv[i];auto next=[&]()->std::string_view{if(++i>=argc)throw std::runtime_error("missing value after "+std::string(a));return argv[i];};if(a=="--experiment")o.file=next();else if(a=="--output")o.output=next();else if(a=="--workers")o.workers=static_cast<std::size_t>(std::stoull(std::string(next())));else if(a=="--case")o.selected_case=next();else if(a=="--help"){std::cout<<"airside_autonomy_experiment --experiment FILE [--workers N] [--output DIR] [--case NAME]\n";std::exit(0);}else throw std::runtime_error("unknown or incomplete option: "+std::string(a));}return o;}
SensorKind parse_sensor(const std::string& s){if(s=="gnss")return SensorKind::Gnss;if(s=="imu")return SensorKind::Imu;if(s=="odometry")return SensorKind::Odometry;if(s=="lidar")return SensorKind::Lidar;throw std::runtime_error("unknown fault sensor: "+s);}
SensorFaultKind parse_kind(const std::string& s){if(s=="dropout")return SensorFaultKind::Dropout;if(s=="noise")return SensorFaultKind::Noise;if(s=="bias")return SensorFaultKind::Bias;if(s=="range_limit")return SensorFaultKind::RangeLimit;if(s=="obstruction")return SensorFaultKind::Obstruction;if(s=="scale")return SensorFaultKind::Scale;if(s=="drift")return SensorFaultKind::Drift;if(s=="delay")return SensorFaultKind::Delay;if(s=="packet_loss")return SensorFaultKind::PacketLoss;if(s=="burst_loss")return SensorFaultKind::BurstLoss;throw std::runtime_error("unknown fault type: "+s);}
std::string sensor_name(SensorKind v){switch(v){case SensorKind::Gnss:return"gnss";case SensorKind::Imu:return"imu";case SensorKind::Odometry:return"odometry";case SensorKind::Lidar:return"lidar";}return"unknown";}
std::string kind_name(SensorFaultKind v){switch(v){case SensorFaultKind::Dropout:return"dropout";case SensorFaultKind::Noise:return"noise";case SensorFaultKind::Bias:return"bias";case SensorFaultKind::RangeLimit:return"range_limit";case SensorFaultKind::Obstruction:return"obstruction";case SensorFaultKind::Scale:return"scale";case SensorFaultKind::Drift:return"drift";case SensorFaultKind::Delay:return"delay";case SensorFaultKind::PacketLoss:return"packet_loss";case SensorFaultKind::BurstLoss:return"burst_loss";}return"unknown";}
std::string fault_label(const std::vector<SensorFault>& fs){std::ostringstream out;out<<std::setprecision(17);bool first=true;for(const auto& f:fs){if(!first)out<<'|';first=false;out<<sensor_name(f.sensor)<<':'<<kind_name(f.kind)<<"@"<<f.start_s<<'+'<<f.duration_s<<";magnitude="<<f.magnitude<<";x_m="<<f.offset.x_m<<";y_m="<<f.offset.y_m<<";probability="<<f.probability<<";angle_min_rad="<<f.angle_min_rad<<";angle_max_rad="<<f.angle_max_rad;}return first?"none":out.str();}
std::string csv_quote(std::string s){std::string out="\"";for(char c:s){if(c=='\"')out+='\"';out+=c;}return out+'\"';}
void assign_faults(AutonomyScenario& scenario,const YAML::Node& node){if(!node)return;for(const auto& f:node){SensorFault x;x.sensor=parse_sensor(f["sensor"].as<std::string>());x.kind=parse_kind(f["type"].as<std::string>());x.start_s=f["start_s"].as<double>();x.duration_s=f["duration_s"].as<double>();x.magnitude=f["magnitude"]?f["magnitude"].as<double>():0.0;x.probability=f["probability"]?f["probability"].as<double>():0.0;x.offset={f["x_m"]?f["x_m"].as<double>():0.0,f["y_m"]?f["y_m"].as<double>():0.0};x.angle_min_rad=(f["angle_min_deg"]?f["angle_min_deg"].as<double>():0.0)*3.14159265358979323846/180.0;x.angle_max_rad=(f["angle_max_deg"]?f["angle_max_deg"].as<double>():0.0)*3.14159265358979323846/180.0;if(x.start_s<0||x.duration_s<=0||x.magnitude<0||x.probability<0||x.probability>1||x.angle_max_rad<x.angle_min_rad)throw std::runtime_error("invalid fault definition in experiment");scenario.faults.push_back(x);}}
}

int main(int argc,char**argv){try{
    const auto opt=parse(argc,argv);const auto root=YAML::LoadFile(opt.file.string());const auto base=opt.file.parent_path();auto base_scenario=load_scenario(base/root["scenario"].as<std::string>());
    const auto seed_start=root["seed_start"]?root["seed_start"].as<std::uint64_t>():42ULL;const auto fault_seed_start=root["fault_seed_start"]?root["fault_seed_start"].as<std::uint64_t>():9001ULL;const auto runs=root["runs_per_case"]?root["runs_per_case"].as<std::size_t>():(root["runs_per_noise_level"]?root["runs_per_noise_level"].as<std::size_t>():1U);const auto workers=opt.workers?opt.workers:(root["workers"]?root["workers"].as<std::size_t>():1U);if(!runs||!workers)throw std::runtime_error("runs_per_case and workers must be positive");
    struct Entry{std::string name;AutonomyScenario scenario;};std::vector<Entry> cases;if(root["cases"]){for(const auto& c:root["cases"]){const auto name=c["name"].as<std::string>();if(!opt.selected_case.empty()&&opt.selected_case!=name)continue;auto s=base_scenario;s.name=name;assign_faults(s,c["faults"]);if(c["gnss_sigma_m"])s.sensors.gnss_sigma_m=c["gnss_sigma_m"].as<double>();auto legacy=s;legacy.name=name+"_legacy";legacy.estimator_enabled=false;cases.push_back({legacy.name,std::move(legacy)});cases.push_back({name,std::move(s)});}}else if(root["gnss_sigma_m"]){for(const auto& level:root["gnss_sigma_m"]){const auto sigma=level.as<double>();const auto name="gnss_noise_sigma_"+std::to_string(sigma);if(!opt.selected_case.empty()&&opt.selected_case!=name)continue;auto s=base_scenario;s.name=name;s.sensors.gnss_sigma_m=sigma;auto legacy=s;legacy.name=name+"_legacy";legacy.estimator_enabled=false;cases.push_back({legacy.name,std::move(legacy)});cases.push_back({name,std::move(s)});}}if(cases.empty())throw std::runtime_error(opt.selected_case.empty()?"experiment has no cases or supported legacy GNSS sigma levels":"selected case was not found: "+opt.selected_case);
    std::vector<AutonomyRunRequest> requests;std::size_t ordinal=0;for(const auto& c:cases)for(std::size_t i=0;i<runs;++i)requests.push_back({c.scenario,seed_start+i,ordinal++,fault_seed_start+i});
    const auto report=execute_runs(std::move(requests),workers);auto output=opt.output.empty()?base/(root["output_directory"]?root["output_directory"].as<std::string>():"../results/autonomy_robustness"):opt.output;std::filesystem::create_directories(output);
    std::ofstream csv(output/"runs.csv"),json(output/"runs.json");if(!csv||!json)throw std::runtime_error("cannot open experiment result outputs");csv<<"scenario,seed,fault_seed,estimator_mode,faults,result,mission_completed,completion_time_s,distance_m,mean_route_error_m,max_route_error_m,min_clearance_m,collisions,emergency_stops,command_timeouts,degraded_entries,safety_stop_entries,time_stopped_degraded_s,messages_generated,messages_dropped,messages_delayed,max_delay_s,unavailable_duration_s,fault_activation_s,fault_deactivation_s,fault_events,final_x_m,final_y_m,final_heading_rad,final_speed_mps,gnss_generated,gnss_delivered,gnss_dropped,gnss_delayed,imu_generated,imu_delivered,imu_dropped,imu_delayed,odometry_generated,odometry_delivered,odometry_dropped,odometry_delayed,lidar_generated,lidar_delivered,lidar_dropped,lidar_delayed,trajectory_digest,mean_position_error_m,rms_position_error_m,max_position_error_m,final_position_error_m,mean_heading_error_rad,max_heading_error_rad,final_heading_error_rad,initialization_time_s,healthy_time_s,degraded_time_s,unsafe_time_s,max_position_uncertainty_m,max_heading_uncertainty_rad,gnss_accepted,gnss_rejected,stale_rejected,gnss_gate_activations,estimator_safety_stops\n";json<<"[\n";
    std::map<std::pair<bool,std::uint64_t>,const AutonomyExperimentRun*> baseline;for(const auto& r:report.runs)if(r.scenario_name=="baseline"||r.scenario_name=="baseline_legacy")baseline[{r.estimator_enabled,r.seed}]=&r;
    for(std::size_t i=0;i<report.runs.size();++i){const auto& r=report.runs[i];const auto&m=r.metrics;const bool success=m.result==MissionResult::Success;const auto activations=[&](){std::string t;for(double x:m.fault_activation_times_s){if(!t.empty())t+=';';t+=std::to_string(x);}return t;}();const auto deactivations=[&](){std::string t;for(double x:m.fault_deactivation_times_s){if(!t.empty())t+=';';t+=std::to_string(x);}return t;}();std::ostringstream events,events_json;events<<std::setprecision(17);events_json<<'[';for(std::size_t e=0;e<m.fault_events.size();++e){if(e){events<<';';events_json<<',';}const auto& event=m.fault_events[e];events<<event.fault_index<<'@'<<event.time_s<<':'<<event.event;events_json<<"{\"fault_index\":";if(event.fault_index==std::numeric_limits<std::size_t>::max())events_json<<"null";else events_json<<event.fault_index;events_json<<",\"time_s\":"<<event.time_s<<",\"event\":"<<csv_quote(event.event)<<'}';}events_json<<']';csv<<csv_quote(r.scenario_name)<<','<<r.seed<<','<<r.fault_seed<<','<<(r.estimator_enabled?"fused":"legacy")<<','<<csv_quote(fault_label(r.faults))<<','<<to_string(m.result)<<','<<(success?1:0)<<','<<m.completion_time_s<<','<<m.distance_traveled_m<<','<<m.mean_route_error_m<<','<<m.maximum_route_error_m<<','<<m.minimum_obstacle_clearance_m<<','<<m.collision_count<<','<<m.emergency_stops<<",0,"<<m.degraded_mode_entries<<','<<m.safety_stop_entries<<','<<m.time_stopped_degraded_s<<','<<(m.gnss_samples+m.imu_samples+m.odometry_samples+m.lidar_scans)<<','<<m.messages_dropped<<','<<m.messages_delayed<<','<<m.maximum_delay_s<<','<<m.unavailable_duration_s<<','<<csv_quote(activations)<<','<<csv_quote(deactivations)<<','<<csv_quote(events.str())<<','<<m.final_x_m<<','<<m.final_y_m<<','<<m.final_heading_rad<<','<<m.final_speed_mps<<','<<m.gnss_samples<<','<<m.gnss_delivered<<','<<m.gnss_dropped<<','<<m.gnss_delayed<<','<<m.imu_samples<<','<<m.imu_delivered<<','<<m.imu_dropped<<','<<m.imu_delayed<<','<<m.odometry_samples<<','<<m.odometry_delivered<<','<<m.odometry_dropped<<','<<m.odometry_delayed<<','<<m.lidar_scans<<','<<m.lidar_delivered<<','<<m.lidar_dropped<<','<<m.lidar_delayed<<','<<m.trajectory_digest<<','<<m.mean_position_error_m<<','<<m.rms_position_error_m<<','<<m.maximum_position_error_m<<','<<m.final_position_error_m<<','<<m.mean_heading_error_rad<<','<<m.maximum_heading_error_rad<<','<<m.final_heading_error_rad<<','<<m.estimator_initialization_time_s<<','<<m.estimator_healthy_time_s<<','<<m.estimator_degraded_time_s<<','<<m.estimator_unsafe_time_s<<','<<m.maximum_position_uncertainty_m<<','<<m.maximum_heading_uncertainty_rad<<','<<m.gnss_updates_accepted<<','<<m.gnss_updates_rejected<<','<<m.stale_measurements_rejected<<','<<m.gnss_gate_activations<<','<<m.estimator_uncertainty_safety_stops<<'\n';
        if(i)json<<",\n";json<<"  {\"scenario\":"<<csv_quote(r.scenario_name)<<",\"seed\":"<<r.seed<<",\"fault_seed\":"<<r.fault_seed<<",\"estimator_mode\":"<<csv_quote(r.estimator_enabled?"fused":"legacy")<<",\"faults\":"<<csv_quote(fault_label(r.faults))<<",\"result\":"<<csv_quote(to_string(m.result))<<",\"mission_completed\":"<<(success?"true":"false")<<",\"completion_time_s\":"<<m.completion_time_s<<",\"distance_m\":"<<m.distance_traveled_m<<",\"mean_route_error_m\":"<<m.mean_route_error_m<<",\"max_route_error_m\":"<<m.maximum_route_error_m<<",\"min_clearance_m\":"<<m.minimum_obstacle_clearance_m<<",\"collisions\":"<<m.collision_count<<",\"emergency_stops\":"<<m.emergency_stops<<",\"command_timeouts\":0,\"degraded_entries\":"<<m.degraded_mode_entries<<",\"safety_stop_entries\":"<<m.safety_stop_entries<<",\"time_stopped_degraded_s\":"<<m.time_stopped_degraded_s<<",\"messages_dropped\":"<<m.messages_dropped<<",\"messages_delayed\":"<<m.messages_delayed<<",\"maximum_delay_s\":"<<m.maximum_delay_s<<",\"unavailable_duration_s\":"<<m.unavailable_duration_s<<",\"fault_activation_times_s\":"<<csv_quote(activations)<<",\"fault_deactivation_times_s\":"<<csv_quote(deactivations)<<",\"fault_events\":"<<events_json.str()<<",\"final_state\":{\"x_m\":"<<m.final_x_m<<",\"y_m\":"<<m.final_y_m<<",\"heading_rad\":"<<m.final_heading_rad<<",\"speed_mps\":"<<m.final_speed_mps<<"},\"sensor_stats\":{\"gnss\":{\"generated\":"<<m.gnss_samples<<",\"delivered\":"<<m.gnss_delivered<<",\"dropped\":"<<m.gnss_dropped<<",\"delayed\":"<<m.gnss_delayed<<"},\"imu\":{\"generated\":"<<m.imu_samples<<",\"delivered\":"<<m.imu_delivered<<",\"dropped\":"<<m.imu_dropped<<",\"delayed\":"<<m.imu_delayed<<"},\"odometry\":{\"generated\":"<<m.odometry_samples<<",\"delivered\":"<<m.odometry_delivered<<",\"dropped\":"<<m.odometry_dropped<<",\"delayed\":"<<m.odometry_delayed<<"},\"lidar\":{\"generated\":"<<m.lidar_scans<<",\"delivered\":"<<m.lidar_delivered<<",\"dropped\":"<<m.lidar_dropped<<",\"delayed\":"<<m.lidar_delayed<<"}},\"estimator\":{\"mean_position_error_m\":"<<m.mean_position_error_m<<",\"rms_position_error_m\":"<<m.rms_position_error_m<<",\"maximum_position_error_m\":"<<m.maximum_position_error_m<<",\"final_position_error_m\":"<<m.final_position_error_m<<",\"mean_heading_error_rad\":"<<m.mean_heading_error_rad<<",\"maximum_heading_error_rad\":"<<m.maximum_heading_error_rad<<",\"final_heading_error_rad\":"<<m.final_heading_error_rad<<",\"initialization_time_s\":"<<m.estimator_initialization_time_s<<",\"healthy_time_s\":"<<m.estimator_healthy_time_s<<",\"degraded_time_s\":"<<m.estimator_degraded_time_s<<",\"unsafe_time_s\":"<<m.estimator_unsafe_time_s<<",\"maximum_position_uncertainty_m\":"<<m.maximum_position_uncertainty_m<<",\"maximum_heading_uncertainty_rad\":"<<m.maximum_heading_uncertainty_rad<<",\"gnss_accepted\":"<<m.gnss_updates_accepted<<",\"gnss_rejected\":"<<m.gnss_updates_rejected<<",\"stale_rejected\":"<<m.stale_measurements_rejected<<",\"gate_activations\":"<<m.gnss_gate_activations<<",\"uncertainty_safety_stops\":"<<m.estimator_uncertainty_safety_stops<<"},\"trajectory_digest\":"<<m.trajectory_digest<<"}";
    }json<<"\n]\n";csv.close();json.close();
    {std::ofstream diagnostics(output/"estimator_diagnostics.csv");if(!diagnostics)throw std::runtime_error("cannot open estimator diagnostics output");diagnostics<<"scenario,seed,fault_seed,mode,wheel_health,gnss_recovery,wheel_inconsistency_count,wheel_health_transitions,wheel_downweighted,gnss_reacquisition_attempts,gnss_reacquisition_successes,gnss_reacquisition_candidates_rejected,localization_degraded_time_s,maximum_position_uncertainty_m,maximum_gnss_nis,safety_stop_time_s,gnss_recovery_latency_s,gnss_accepted,gnss_rejected,gnss_gate_activations\n";for(const auto& r:report.runs){const auto&m=r.metrics;diagnostics<<csv_quote(r.scenario_name)<<','<<r.seed<<','<<r.fault_seed<<','<<(r.estimator_enabled?"fused":"legacy")<<','<<static_cast<int>(m.final_wheel_health)<<','<<static_cast<int>(m.final_gnss_recovery)<<','<<m.wheel_inconsistency_count<<','<<m.wheel_health_transitions<<','<<m.wheel_downweighted<<','<<m.gnss_reacquisition_attempts<<','<<m.gnss_reacquisition_successes<<','<<m.gnss_reacquisition_candidates_rejected<<','<<m.localization_degraded_time_s<<','<<m.maximum_position_uncertainty_m<<','<<m.maximum_gnss_nis<<','<<m.estimator_safety_stop_time_s<<','<<m.gnss_recovery_latency_s<<','<<m.gnss_updates_accepted<<','<<m.gnss_updates_rejected<<','<<m.gnss_gate_activations<<'\n';}}
    std::cout<<std::fixed<<std::setprecision(3)<<"Robustness experiment: "<<root["name"].as<std::string>()<<"\nRuns: "<<report.runs.size()<<" workers: "<<report.worker_count<<" wall: "<<report.wall_time.count()<<" s\nResults: "<<std::filesystem::absolute(output).string()<<"\n";
    for(const auto& r:report.runs)if(r.scenario_name!="baseline"&&r.scenario_name!="baseline_legacy"){const auto it=baseline.find({r.estimator_enabled,r.seed});if(it!=baseline.end()){const auto&b=it->second->metrics;std::cout<<r.scenario_name<<" ["<<(r.estimator_enabled?"fused":"legacy")<<"] seed "<<r.seed<<": "<<to_string(r.metrics.result)<<", time delta "<<r.metrics.completion_time_s-b.completion_time_s<<" s, max route-error delta "<<r.metrics.maximum_route_error_m-b.maximum_route_error_m<<" m, clearance delta "<<r.metrics.minimum_obstacle_clearance_m-b.minimum_obstacle_clearance_m<<" m, position RMSE "<<r.metrics.rms_position_error_m<<" m, GNSS gate activations "<<r.metrics.gnss_gate_activations<<", safety stops "<<r.metrics.safety_stop_entries<<'\n';}}
    return 0;
}catch(const std::exception&e){std::cerr<<"autonomy experiment: "<<e.what()<<'\n';return 1;}}
